cd /tmp && timeout 25 python - <<'EOF'
import numpy as np
from numba import stencil, njit

@stencil('wrap')
def k(a, b):
    return a[-1] + b[1]

@njit(parallel=True)
def par(a, b):
    return k(a, b)

a = np.arange(5.)+1
b = np.arange(5.)*10
got = par(a, b)
n=5
exp = np.empty_like(a)
for i in range(n):
    exp[i] = a[(i-1)%n] + b[(i+1)%n]
print("par multi input wrap:", np.allclose(got, exp))
assert np.allclose(got, exp)
print("OK")
